#include <iostream>
#include <list>
int main() {
    std::list<int> l = {1, 2, 3};
    auto it = std::next(l.begin());   // 指向 2
    l.insert(it, 9);                   // 在 2 前插入 9 -> {1,9,2,3}
    l.erase(std::next(l.begin(), 2));  // 删除下标定 2 的元素（值为 2）
    for (int x : l) std::cout << x << ' ';
    std::cout << '\n';
    std::cout << "size=" << l.size() << '\n';
}
